-- 123: Original BrillaPrep WASSCE BrillaPrep IRS beta content blueprint beta questions, part 2.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_123_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_123_guard;
INSERT INTO _migration_123_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_006' AND NOT (q.topic_id IS 'topic_was_irs_2' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the isnad of a Hadith?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The main mosque of a city","B. The chain of people who transmitted the report","C. The legal ruling derived from trade","D. The written chapter heading"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Hadith scholars examine the isnad to identify transmitters and assess continuity and reliability alongside analysis of the reported text. Therefore the correct answer is B: The chain of people who transmitted the report.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_006' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_123_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_007' AND NOT (q.topic_id IS 'topic_was_irs_2' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the matn of a Hadith?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The chain of transmitters","B. A tax on agricultural produce","C. The actual reported wording or content","D. The direction of prayer"]' AND q.correct_answer IS 'C' AND q.explanation IS 'A Hadith has a chain of transmission and a reported text. Both require examination when scholars assess authenticity and meaning. Therefore the correct answer is C: The actual reported wording or content.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_007' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_123_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_008' AND NOT (q.topic_id IS 'topic_was_irs_2' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which description best fits a sahih Hadith?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Every story circulated without a chain","B. A report known to contain a fabricated narrator","C. Any statement that agrees with personal preference","D. A report meeting strong conditions of continuity and reliable transmission"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Sahih classification depends on connected transmission, trustworthy precise narrators and freedom from disqualifying irregularity or hidden defect. Therefore the correct answer is D: A report meeting strong conditions of continuity and reliable transmission.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_2' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_008' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_123_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_009' AND NOT (q.topic_id IS 'topic_was_irs_2' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How does Sunnah differ from an individual Hadith report?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Sunnah is the Prophet’s normative example, while Hadith reports transmit information about it","B. Sunnah is a chapter of the Qur’an","C. Hadith is always later custom with no chain","D. The two terms refer only to buildings"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Hadith is a vehicle through which sayings, actions and approvals are reported, while Sunnah describes the Prophetic model followed in Muslim life. Therefore the correct answer is A: Sunnah is the Prophet’s normative example, while Hadith reports transmit information about it.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_2' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_009' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_123_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_irs_b001_010' AND NOT (q.topic_id IS 'topic_was_irs_2' AND q.subject_id IS 'subj_wassce_irs' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why was Umar ibn Abd al-Aziz important in Hadith history?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. He prohibited all written scholarship","B. He ordered scholars to collect Hadith before knowledge and transmitters were lost","C. He replaced the Qur’an with biographies","D. He was the first caller to prayer in Makkah"]' AND q.correct_answer IS 'B' AND q.explanation IS 'His official encouragement helped move Hadith collection toward organised preservation at a time when knowledgeable transmitters were disappearing. Therefore the correct answer is B: He ordered scholars to collect Hadith before knowledge and transmitters were lost.' AND q.difficulty IS 'easy' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_irs_2' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_irs_b001_010' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to published WAEC Islamic Studies learning evidence; not official WAEC examination material.' AND r.source_url IS 'https://waecgh.org/home/wassce-school/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
